import { confirm } from "../../dialogs";
import { logger } from "../../logger";

/**
 * Header sent on R2 write requests to ask the API to reject the operation if a
 * data catalog is enabled for the bucket. When omitted, the operation proceeds
 * without the safety check.
 */
export const R2_DATA_CATALOG_CHECK_HEADER = "cf-r2-data-catalog-check";

/**
 * Error code returned (alongside HTTP 409) when a write is blocked because the
 * bucket has a data catalog enabled.
 */
const R2_DATA_CATALOG_CONFLICT_CODE = 10081;

/**
 * The confirmation prompt shown when a per-operation write conflicts with a
 * bucket's data catalog.
 */
const DATA_CATALOG_CONFLICT_PROMPT =
	"Data catalog is enabled for this bucket. Proceeding may leave the data catalog in an invalid state. Continue?";

/**
 * Whether the given error is the R2 data catalog conflict (HTTP 409, code 10081).
 */
export function isDataCatalogConflict(error: unknown): boolean {
	return (
		error instanceof APIError && error.code === R2_DATA_CATALOG_CONFLICT_CODE
	);
}

/**
 * Run a write operation that could conflict with a bucket's data catalog.
 *
 * When `force` is `false`, the operation is first attempted with the data
 * catalog check enabled. If the API rejects the request because a data catalog
 * is enabled, the user is prompted before retrying the operation without the
 * check. When `force` is `true`, the check is skipped entirely.
 *
 * @param force Whether to bypass the data catalog check (from `--force`/`-y`).
 * @param operation Performs the write; receives whether to send the check header.
 * @returns `true` if the operation completed, `false` if the user cancelled.
 */
export async function withDataCatalogCheck(
	force: boolean,
	operation: (dataCatalogCheck: boolean) => Promise<void>
): Promise<boolean> {
	if (force) {
		await operation(false);
		return true;
	}

	try {
		await operation(true);
		return true;
	} catch (e) {
		if (!isDataCatalogConflict(e)) {
			throw e;
		}

		const confirmed = await confirm(DATA_CATALOG_CONFLICT_PROMPT);
		if (!confirmed) {
			logger.log("Operation cancelled.");
			return false;
		}

		await operation(false);
		return true;
	}
}
